"use client";

import { useEffect, useState } from "react";

// =========================================================================
// One place for "who is signed in right now". Client components should read
// the citizen's name from here rather than from the mock fixtures, which is
// what made the whole app insist everyone was Priya Sharma.
// =========================================================================

export interface CitizenProfileData {
  id: string;
  username: string | null;
  fullName: string;
  email: string | null;
  locality: string | null;
  tier: string;
  pointsBalance: number;
}

export function useCitizenProfile() {
  const [profile, setProfile] = useState<CitizenProfileData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    fetch("/api/profile", { cache: "no-store" })
      .then((res) => (res.ok ? res.json() : null))
      .then((data: CitizenProfileData | null) => {
        if (!cancelled) setProfile(data);
      })
      .catch(() => {
        if (!cancelled) setProfile(null);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  return { profile, loading };
}
